from pathlib import Path
import re,json
root=Path(__file__).resolve().parent.parent
source=(root/'koncepcio-1-csendes-enido.html').read_text(encoding='utf-8')
css=re.search(r'<style>(.*?)</style>',source,re.S)[1]
def section(pattern):
    found=re.search(pattern,source,re.S)
    assert found,pattern
    return found[0]
colors=[('Rózsafa','#8E4A5A','Gomb és link'),('Sötét rózsafa','#6E3644','Hover'),('Homokarany','#C9A27E','Díszítés'),('Krém','#FAF6F2','Oldalháttér'),('Púder','#F1E6DF','Felület'),('Kakaó','#2E2626','Szöveg és lábléc'),('Szürkésbarna','#6B5F5C','Másodlagos szöveg'),('Halvány púder','#E3D6CF','Elválasztó')]
swatches=''.join(f'<div class="swatch"><span style="background:{hex}"></span><strong>{name}</strong><code>{hex}</code><small>{role}</small></div>' for name,hex,role in colors)
def luminance(color):
    values=[int(color[i:i+2],16)/255 for i in (1,3,5)]
    values=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in values]
    return sum(a*b for a,b in zip(values,[.2126,.7152,.0722]))
ratios=[]
for name,a,b in [('Kakaó / krém','#2E2626','#FAF6F2'),('Másodlagos / krém','#6B5F5C','#FAF6F2'),('Másodlagos / púder','#6B5F5C','#F1E6DF'),('Fehér / rózsafa','#FFFFFF','#8E4A5A'),('Rózsafa / krém','#8E4A5A','#FAF6F2')]:
    l1,l2=sorted([luminance(a),luminance(b)])
    ratios.append((name,round((l2+.05)/(l1+.05),2)))
contrast=''.join(f'<li>{name}: <strong>{ratio}:1</strong></li>' for name,ratio in ratios)
cards=section(r'<section class="section wrap treatments-redesign".*?</section>')
gallery=section(r'<section class="wrap care-gallery".*?</section>')
contact=section(r'<section class="section wrap contact".*?</section>')
newsletter=section(r'<section class="wrap" id="kisokos">.*?</section>')
frame=section(r'<figure class="photo-frame">.*?</figure>')
detail=section(r'<figure class="photo-frame detail-frame">.*?</figure>')
faq='<div class="faq">'+section(r'<details><summary>Időpont nélkül.*?</details>')+section(r'<details><summary>Honnan tudjam.*?</details>')+'</div>'
dialog=section(r'<dialog class="privacy".*?</dialog>')
extra='''
.guide-nav{padding:24px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:24px;align-items:center}.guide-nav img{width:110px}.guide-nav a{color:var(--color-brand-primary);text-decoration:underline}.guide-shell{max-width:1280px;margin:auto;padding:0 40px}.guide-intro{padding:64px 0}.guide-intro h1{max-width:850px}.guide-intro p{max-width:650px;margin-top:24px}.guide-toc{display:flex;gap:16px 24px;flex-wrap:wrap;margin-top:32px;font-size:16px}.guide-toc a{border-bottom:1px solid var(--line)}.guide-group{padding:64px 0;border-top:1px solid var(--line);scroll-margin-top:24px}.guide-heading{font:500 28px/1.2 var(--font-heading);margin-bottom:20px}.guide-note{font-size:15px;max-width:760px;margin-bottom:32px}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.swatch{background:white;border:1px solid var(--line);border-radius:16px;overflow:hidden;padding-bottom:20px}.swatch>span{display:block;height:100px;border-bottom:1px solid var(--line)}.swatch strong,.swatch code,.swatch small{display:block;margin:8px 20px 0}.swatch strong{font-size:16px;font-weight:500}.swatch code{font:14px var(--font-body)}.swatch small{font-size:13px;color:var(--color-brand-muted)}.contrast-list{display:flex;flex-wrap:wrap;gap:12px 32px;list-style:none;padding:0;margin-top:32px;font-size:15px}.guide-type{display:grid;gap:24px}.guide-type small{display:block;font:14px var(--font-body);color:var(--color-brand-muted);margin-bottom:8px}.type-h1{font:500 var(--text-h1)/1.12 var(--font-heading);letter-spacing:-.025em}.type-h2{font:500 var(--text-h2)/1.12 var(--font-heading)}.type-h3{font:600 28px/1.2 var(--font-heading)}.guide-images{display:grid;grid-template-columns:1fr 1fr;gap:80px;padding:24px 20px}.guide-images img{height:420px;width:100%;object-fit:cover}.guide-group>.section,.guide-group>.wrap{padding-top:0;padding-bottom:0;width:100%;max-width:none}.guide-group .contact{margin-top:0}.guide-error{border-color:var(--color-brand-secondary);background:#FAF6F2}.guide-error-note{font-size:14px;color:var(--color-brand-secondary);margin-top:8px}.guide-field{max-width:480px}.guide-footer{padding:40px 0;color:var(--color-brand-muted);font-size:14px}.guide-group .treatments-heading{display:none}.guide-group .gallery-heading{display:none}#forms .contact .opening-panel{margin-top:24px}.guide-button-row{display:flex;gap:16px;flex-wrap:wrap}button:disabled{opacity:.55;cursor:not-allowed}.guide-group #kapcsolat{scroll-margin-top:20px}
@media(max-width:760px){.guide-shell{padding:0 20px}.guide-intro{padding:40px 0}.guide-group{padding:48px 0}.swatches{grid-template-columns:1fr 1fr;gap:16px}.guide-images{grid-template-columns:1fr;gap:48px;padding:16px}.guide-images img{height:340px}.guide-nav{align-items:start}.guide-nav a{font-size:14px}}
'''
html=f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eliza Beauty Salon — Design system 1.0</title><meta name="robots" content="noindex"><link rel="icon" href="../logo/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Jost:wght@400;500&display=swap" rel="stylesheet"><style>{css}</style><link rel="stylesheet" href="tokens.css"><style>{extra}</style></head><body><div class="guide-shell"><header class="guide-nav"><img src="../logo/logo.svg" alt="Eliza Beauty Salon"><a href="../koncepcio-1-csendes-enido.html">Kiválasztott kezdőoldal</a></header><main><div class="guide-intro"><div class="kicker">Belső márka- és komponensútmutató · 1.0</div><h1>A személyes törődés vizuális rendszere.</h1><p>A kiválasztott első koncepció színei, formái és komponensei. Ebből épülnek majd az egységes Kezelések, Rólunk és Kapcsolat oldalak.</p><nav class="guide-toc" aria-label="Mintatár tartalma"><a href="#colors">Színek</a><a href="#type">Betűk</a><a href="#buttons">Gombok</a><a href="#photos">Képkeretek</a><a href="#cards">Kártyák</a><a href="#gallery">Galéria</a><a href="#newsletter">Kisokos</a><a href="#forms">Kapcsolat</a><a href="#states">Állapotok</a></nav></div>
<section id="colors" class="guide-group"><h2 class="guide-heading">Színek és szerepek</h2><p class="guide-note">Krém és púder felületek, rózsafa cselekvési pontok. A homokarany kizárólag dekoratív részlet.</p><div class="swatches">{swatches}</div><ul class="contrast-list">{contrast}</ul></section>
<section id="type" class="guide-group"><h2 class="guide-heading">Tipográfia</h2><div class="guide-type"><div><small>H1 · Cormorant Garamond 500 · 40–64 px</small><div class="type-h1">A bőröd egészsége.</div></div><div><small>H2 · Cormorant Garamond 500 · 32–44 px</small><div class="type-h2">Személyes figyelem, szakértő kezek.</div></div><div><small>H3 · Cormorant Garamond 600 · 28 px</small><div class="type-h3">A hozzád illő kezelés</div></div><div><small>Törzs · Jost 400 · 18 / 16 px · 1.65 sormagasság</small><p>Az első találkozáskor megismerem a bőröd igényeit, és együtt találjuk meg a számodra megfelelő ápolást. Árvíztűrő tükörfúrógép.</p></div><div class="kicker">Rövid felirat, finom vonallal</div></div></section>
<section id="buttons" class="guide-group"><h2 class="guide-heading">Gombok és fókusz</h2><p class="guide-note">A Tab billentyűvel nézd meg a fókuszt. Az elsődleges cselekvés rózsafa, a másodlagos keretezett.</p><div class="guide-button-row"><a class="btn" href="#kapcsolat">Időpontot kérek</a><a class="btn secondary" href="#cards">Megnézem a kezeléseket</a><button class="btn" disabled>Nem elérhető</button></div></section>
<section id="photos" class="guide-group"><h2 class="guide-heading">Íves képek és eltolt keretek</h2><p class="guide-note">A két hangsúlyos képszerep: íves nyitókép és aszimmetrikus részletkép. A keret mögött finom alátét van; nincs végigfutó grafikai vonal.</p><div class="guide-images">{frame}{detail}</div></section>
<section id="cards" class="guide-group"><h2 class="guide-heading">Kezelési kártyák</h2><p class="guide-note">Három egyenlő kártya, kezelési fotóval és alul igazított hivatkozással; mobilon egymás alatt.</p>{cards}</section>
<section id="gallery" class="guide-group"><h2 class="guide-heading">Elcsúsztatott galéria</h2><p class="guide-note">Három különböző fotó, eltérő kerettel. Mobilon oldalra lapozható, automatikus váltás nélkül.</p>{gallery}</section>
<section id="newsletter" class="guide-group"><h2 class="guide-heading">Kisokos és feliratkozás</h2><p class="guide-note">Asztali nézetben balra a form, jobbra a szöveg és a 17-es kép. Mobilon előbb a magyarázat jelenik meg. Bemutató, adatot nem küld.</p>{newsletter}</section>
<section id="forms" class="guide-group"><h2 class="guide-heading">Kapcsolat és nyitvatartás</h2><p class="guide-note">Egy magasságban végződő oszlopok; kompakt nyitvatartás, pötty nélkül, eltolt rózsafa kontúrral. A mintaelérhetőségek a tanfolyami projekt adatai.</p>{contact}</section>
<section id="states" class="guide-group"><h2 class="guide-heading">GYIK és űrlapállapotok</h2>{faq}<div class="guide-field" style="margin-top:40px"><h3>Javasolt hibaállapot az éles űrlaphoz</h3><p class="guide-note" style="margin-top:16px">Ez még nem bekötött validáció, hanem hozzáférhető megjelenési minta.</p><label for="sample-error">E-mail cím<input class="guide-error" id="sample-error" type="email" value="pelda@" aria-invalid="true" aria-describedby="sample-error-note"></label><p id="sample-error-note" class="guide-error-note">Adj meg egy teljes e-mail-címet, például nev@pelda.hu.</p></div></section></main><footer class="guide-footer">Eliza Beauty Salon · Design system 1.0 · Belső munkaanyag<br><a href="../design-system.md">Részletes szabályok</a> · <a href="tokens.css">CSS-tokenek</a></footer></div>{dialog}<script>document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{{e.preventDefault();form.querySelector('[role=status]').textContent='Komponensbemutató: nem küldtünk adatot.'}}));const dialog=document.querySelector('dialog');document.querySelectorAll('[data-privacy]').forEach(a=>a.addEventListener('click',e=>{{e.preventDefault();dialog.showModal()}}));document.getElementById('privacy-close').addEventListener('click',()=>dialog.close());</script></body></html>'''
# All selected assets live one directory above this internal guide.
html=html.replace('src="images/','src="../images/').replace('srcset="images/','srcset="../images/').replace(', images/',', ../images/')
(root/'design-system/index.html').write_text(html,encoding='utf-8')
(root/'.webprojekt/design-system-contrast.json').write_text(json.dumps(ratios,ensure_ascii=False,indent=2),encoding='utf-8')
print('Design system mintatár és számított kontrasztlista elkészült.')
